     var usage=o&&o.usage||{},input=+usage.input_tokens||0,output=+usage.output_tokens||0,total=+usage.total_tokens||input+output;
     recordTokenUsage({provider:'openai',model:model,input:input,output:output,total:total,estimated:false});
