  var q='?limit='+encodeURIComponent(Math.max(1,Math.min(100,+args.limit||50)));
  if(args.source)q+='&source='+encodeURIComponent(String(args.source).slice(0,48));
  if(args.since)q+='&since='+encodeURIComponent(+args.since||0);
  return communicationInternal('GET','/communication/v1/events'+q,null,cb);
